/**
 * File: p2p-kids-marketplace/src/components/__tests__/listing/PhotoUploadManager.test.tsx
 * MODULE-04 LISTING-V3-008: Unit tests for PhotoUploadManager
 * 
 * Test Coverage:
 * - Rendering with 0, 1, 5, 10 photos
 * - Cover badge on first photo
 * - Add button visibility (< 10 photos)
 * - Remove photo functionality
 * - Max photos enforcement
 * - Accessibility labels
 */

import React from 'react';
import { render, fireEvent, screen } from '@testing-library/react-native';
import { PhotoUploadManager } from '../../listing/PhotoUploadManager';
import { PhotoAsset } from '../../../types/listing';

const mockPhotos: PhotoAsset[] = [
  { id: '1', uri: 'https://example.com/photo1.jpg', fileName: 'photo1.jpg', fileSize: 1024 },
  { id: '2', uri: 'https://example.com/photo2.jpg', fileName: 'photo2.jpg', fileSize: 2048 },
  { id: '3', uri: 'https://example.com/photo3.jpg', fileName: 'photo3.jpg', fileSize: 3072 },
];

describe('PhotoUploadManager', () => {
  const mockOnAddPhotos = jest.fn();
  const mockOnRemovePhoto = jest.fn();
  const mockOnReorder = jest.fn();

  beforeEach(() => {
    jest.clearAllMocks();
  });

  describe('Rendering', () => {
    it('renders with no photos', () => {
      const { getByTestId, getByText } = render(
        <PhotoUploadManager
          photos={[]}
          onAddPhotos={mockOnAddPhotos}
          onRemovePhoto={mockOnRemovePhoto}
          onReorder={mockOnReorder}
        />
      );

      expect(getByTestId('photo-upload-manager')).toBeTruthy();
      expect(getByText('Photos *')).toBeTruthy();
      expect(getByTestId('add-photos-button')).toBeTruthy();
    });

    it('renders with photos', () => {
      const { getAllByTestId } = render(
        <PhotoUploadManager
          photos={mockPhotos}
          onAddPhotos={mockOnAddPhotos}
          onRemovePhoto={mockOnRemovePhoto}
          onReorder={mockOnReorder}
        />
      );

      expect(getAllByTestId(/remove-photo-/).length).toBe(3);
    });

    it('displays (0/10 photos) count when empty', () => {
      const { getByText } = render(
        <PhotoUploadManager
          photos={[]}
          onAddPhotos={mockOnAddPhotos}
          onRemovePhoto={mockOnRemovePhoto}
          onReorder={mockOnReorder}
        />
      );

      expect(getByText('(0/10 photos)')).toBeTruthy();
    });

    it('displays correct count with photos', () => {
      const { getByText } = render(
        <PhotoUploadManager
          photos={mockPhotos}
          onAddPhotos={mockOnAddPhotos}
          onRemovePhoto={mockOnRemovePhoto}
          onReorder={mockOnReorder}
        />
      );

      expect(getByText('(3/10 photos)')).toBeTruthy();
    });
  });

  describe('Cover Badge', () => {
    it('marks first photo as "Cover"', () => {
      const { getByText } = render(
        <PhotoUploadManager
          photos={mockPhotos}
          onAddPhotos={mockOnAddPhotos}
          onRemovePhoto={mockOnRemovePhoto}
          onReorder={mockOnReorder}
        />
      );

      expect(getByText('Cover')).toBeTruthy();
    });

    it('only shows Cover badge once', () => {
      const { getAllByText } = render(
        <PhotoUploadManager
          photos={mockPhotos}
          onAddPhotos={mockOnAddPhotos}
          onRemovePhoto={mockOnRemovePhoto}
          onReorder={mockOnReorder}
        />
      );

      const coverBadges = getAllByText('Cover');
      expect(coverBadges.length).toBe(1);
    });
  });

  describe('Add Photos', () => {
    it('shows Add Photos button when under limit', () => {
      const { getByTestId } = render(
        <PhotoUploadManager
          photos={mockPhotos}
          onAddPhotos={mockOnAddPhotos}
          onRemovePhoto={mockOnRemovePhoto}
          onReorder={mockOnReorder}
        />
      );

      expect(getByTestId('add-photos-button')).toBeTruthy();
    });

    it('calls onAddPhotos when Add button is pressed', () => {
      const { getByTestId } = render(
        <PhotoUploadManager
          photos={mockPhotos}
          onAddPhotos={mockOnAddPhotos}
          onRemovePhoto={mockOnRemovePhoto}
          onReorder={mockOnReorder}
        />
      );

      fireEvent.press(getByTestId('add-photos-button'));
      expect(mockOnAddPhotos).toHaveBeenCalledTimes(1);
    });

    it('hides Add Photos button when at max (10 photos)', () => {
      const tenPhotos: PhotoAsset[] = Array.from({ length: 10 }, (_, i) => ({
        id: String(i + 1),
        uri: `https://example.com/photo${i + 1}.jpg`,
        fileName: `photo${i + 1}.jpg`,
        fileSize: 1024,
      }));

      const { queryByTestId, getByText } = render(
        <PhotoUploadManager
          photos={tenPhotos}
          onAddPhotos={mockOnAddPhotos}
          onRemovePhoto={mockOnRemovePhoto}
          onReorder={mockOnReorder}
        />
      );

      expect(queryByTestId('add-photos-button')).toBeNull();
      expect(getByText('Maximum 10 photos reached')).toBeTruthy();
    });
  });

  describe('Remove Photos', () => {
    it('calls onRemovePhoto with correct photo ID', () => {
      const { getByTestId } = render(
        <PhotoUploadManager
          photos={mockPhotos}
          onAddPhotos={mockOnAddPhotos}
          onRemovePhoto={mockOnRemovePhoto}
          onReorder={mockOnReorder}
        />
      );

      fireEvent.press(getByTestId('remove-photo-1'));
      expect(mockOnRemovePhoto).toHaveBeenCalledWith('1');
    });

    it('shows remove button for all photos', () => {
      const { getByTestId } = render(
        <PhotoUploadManager
          photos={mockPhotos}
          onAddPhotos={mockOnAddPhotos}
          onRemovePhoto={mockOnRemovePhoto}
          onReorder={mockOnReorder}
        />
      );

      expect(getByTestId('remove-photo-1')).toBeTruthy();
      expect(getByTestId('remove-photo-2')).toBeTruthy();
      expect(getByTestId('remove-photo-3')).toBeTruthy();
    });
  });

  describe('Custom Max Photos', () => {
    it('respects custom maxPhotos prop', () => {
      const { getByText } = render(
        <PhotoUploadManager
          photos={mockPhotos}
          onAddPhotos={mockOnAddPhotos}
          onRemovePhoto={mockOnRemovePhoto}
          onReorder={mockOnReorder}
          maxPhotos={5}
        />
      );

      expect(getByText('(3/5 photos)')).toBeTruthy();
    });

    it('shows max limit message for custom max', () => {
      const fivePhotos: PhotoAsset[] = Array.from({ length: 5 }, (_, i) => ({
        id: String(i + 1),
        uri: `https://example.com/photo${i + 1}.jpg`,
        fileName: `photo${i + 1}.jpg`,
        fileSize: 1024,
      }));

      const { getByText } = render(
        <PhotoUploadManager
          photos={fivePhotos}
          onAddPhotos={mockOnAddPhotos}
          onRemovePhoto={mockOnRemovePhoto}
          onReorder={mockOnReorder}
          maxPhotos={5}
        />
      );

      expect(getByText('Maximum 5 photos reached')).toBeTruthy();
    });
  });

  describe('Accessibility', () => {
    it('has accessible label for Add Photos button', () => {
      const { getByLabelText } = render(
        <PhotoUploadManager
          photos={mockPhotos}
          onAddPhotos={mockOnAddPhotos}
          onRemovePhoto={mockOnRemovePhoto}
          onReorder={mockOnReorder}
        />
      );

      expect(getByLabelText('Add photos')).toBeTruthy();
    });

    it('has accessible hints for photos remaining', () => {
      const { getByA11yHint } = render(
        <PhotoUploadManager
          photos={mockPhotos}
          onAddPhotos={mockOnAddPhotos}
          onRemovePhoto={mockOnRemovePhoto}
          onReorder={mockOnReorder}
        />
      );

      expect(getByA11yHint('You can add 7 more photos')).toBeTruthy();
    });

    it('has accessible labels for remove buttons', () => {
      const { getByLabelText } = render(
        <PhotoUploadManager
          photos={mockPhotos}
          onAddPhotos={mockOnAddPhotos}
          onRemovePhoto={mockOnRemovePhoto}
          onReorder={mockOnReorder}
        />
      );

      expect(getByLabelText('Remove photo 1')).toBeTruthy();
      expect(getByLabelText('Remove photo 2')).toBeTruthy();
      expect(getByLabelText('Remove photo 3')).toBeTruthy();
    });
  });

  describe('Custom testID', () => {
    it('uses custom testID when provided', () => {
      const { getByTestId } = render(
        <PhotoUploadManager
          photos={mockPhotos}
          onAddPhotos={mockOnAddPhotos}
          onRemovePhoto={mockOnRemovePhoto}
          onReorder={mockOnReorder}
          testID="custom-test-id"
        />
      );

      expect(getByTestId('custom-test-id')).toBeTruthy();
    });
  });
});

/**
 * File: p2p-kids-marketplace/src/components/__tests__/listing/AIAnalysisCard.test.tsx
 * MODULE-04 LISTING-V3-008: Unit tests for AIAnalysisCard
 * 
 * Test Coverage:
 * - Rendering with AI results
 * - Apply All button (skips filled fields)
 * - Per-field Use buttons
 * - Confidence indicators (high/medium/low)
 * - Dismiss functionality
 * - Entrance animation
 */

import React from 'react';
import { render, fireEvent } from '@testing-library/react-native';
import { AIAnalysisCard } from '../../listing/AIAnalysisCard';
import { AIAnalysisResult } from '../../../types/listing';

const mockAnalysis: AIAnalysisResult = {
  title: {
    value: 'Nike Air Max Sneakers Size 5',
    confidence: 0.85,
  },
  category: {
    value: { id: 'cat-123', label: 'Shoes', icon: '👟' },
    confidence: 0.92,
  },
  condition: {
    value: 'good',
    confidence: 0.75,
  },
  brand: {
    value: 'Nike',
    confidence: 0.88,
  },
  color: {
    value: ['Blue', 'White'],
    confidence: 0.70,
  },
  age_group: {
    value: '6-8',
    confidence: 0.65,
  },
  gender: {
    value: 'boy',
    confidence: 0.55,
  },
};

describe('AIAnalysisCard', () => {
  const mockIsFieldFilled = jest.fn();
  const mockOnApplyAll = jest.fn();
  const mockOnApplyField = jest.fn();
  const mockOnDismiss = jest.fn();

  beforeEach(() => {
    jest.clearAllMocks();
    mockIsFieldFilled.mockReturnValue(false);
  });

  describe('Rendering', () => {
    it('renders with AI analysis', () => {
      const { getByText, getByTestId } = render(
        <AIAnalysisCard
          analysis={mockAnalysis}
          isFieldFilled={mockIsFieldFilled}
          onApplyAll={mockOnApplyAll}
          onApplyField={mockOnApplyField}
          onDismiss={mockOnDismiss}
        />
      );

      expect(getByTestId('ai-analysis-card')).toBeTruthy();
      expect(getByText('🤖 AI Suggestions')).toBeTruthy();
    });

    it('displays all AI suggested fields', () => {
      const { getByText } = render(
        <AIAnalysisCard
          analysis={mockAnalysis}
          isFieldFilled={mockIsFieldFilled}
          onApplyAll={mockOnApplyAll}
          onApplyField={mockOnApplyField}
          onDismiss={mockOnDismiss}
        />
      );

      expect(getByText('Nike Air Max Sneakers Size 5')).toBeTruthy();
      expect(getByText('Shoes')).toBeTruthy();
      expect(getByText('good')).toBeTruthy();
      expect(getByText('Nike')).toBeTruthy();
      expect(getByText('Blue, White')).toBeTruthy();
      expect(getByText('6-8')).toBeTruthy();
      expect(getByText('boy')).toBeTruthy();
    });
  });

  describe('Confidence Indicators', () => {
    it('displays "High" for confidence >= 0.7', () => {
      const { getAllByText } = render(
        <AIAnalysisCard
          analysis={mockAnalysis}
          isFieldFilled={mockIsFieldFilled}
          onApplyAll={mockOnApplyAll}
          onApplyField={mockOnApplyField}
          onDismiss={mockOnDismiss}
        />
      );

      const highConfidence = getAllByText(/High/);
      expect(highConfidence.length).toBeGreaterThan(0);
    });

    it('displays "Medium" for confidence 0.4-0.69', () => {
      const { getByText } = render(
        <AIAnalysisCard
          analysis={mockAnalysis}
          isFieldFilled={mockIsFieldFilled}
          onApplyAll={mockOnApplyAll}
          onApplyField={mockOnApplyField}
          onDismiss={mockOnDismiss}
        />
      );

      // age_group has confidence 0.65 and gender has 0.55
      const mediumConfidence = getAllByText(/Medium/);
      expect(mediumConfidence.length).toBeGreaterThan(0);
    });

    it('displays "Low" for confidence < 0.4', () => {
      const lowConfidenceAnalysis: AIAnalysisResult = {
        title: {
          value: 'Uncertain Item',
          confidence: 0.35,
        },
      };

      const { getByText } = render(
        <AIAnalysisCard
          analysis={lowConfidenceAnalysis}
          isFieldFilled={mockIsFieldFilled}
          onApplyAll={mockOnApplyAll}
          onApplyField={mockOnApplyField}
          onDismiss={mockOnDismiss}
        />
      );

      expect(getByText(/Low/)).toBeTruthy();
    });

    it('displays confidence percentage', () => {
      const { getByText } = render(
        <AIAnalysisCard
          analysis={mockAnalysis}
          isFieldFilled={mockIsFieldFilled}
          onApplyAll={mockOnApplyAll}
          onApplyField={mockOnApplyField}
          onDismiss={mockOnDismiss}
        />
      );

      expect(getByText(/85%/)).toBeTruthy(); // title
      expect(getByText(/92%/)).toBeTruthy(); // category
    });
  });

  describe('Apply All Button', () => {
    it('renders Apply All button', () => {
      const { getByTestId } = render(
        <AIAnalysisCard
          analysis={mockAnalysis}
          isFieldFilled={mockIsFieldFilled}
          onApplyAll={mockOnApplyAll}
          onApplyField={mockOnApplyField}
          onDismiss={mockOnDismiss}
        />
      );

      expect(getByTestId('apply-all-button')).toBeTruthy();
    });

    it('calls onApplyAll when button is pressed', () => {
      const { getByTestId } = render(
        <AIAnalysisCard
          analysis={mockAnalysis}
          isFieldFilled={mockIsFieldFilled}
          onApplyAll={mockOnApplyAll}
          onApplyField={mockOnApplyField}
          onDismiss={mockOnDismiss}
        />
      );

      fireEvent.press(getByTestId('apply-all-button'));
      expect(mockOnApplyAll).toHaveBeenCalledTimes(1);
    });
  });

  describe('Per-Field Use Buttons', () => {
    it('renders Use button for each field', () => {
      const { getByTestId } = render(
        <AIAnalysisCard
          analysis={mockAnalysis}
          isFieldFilled={mockIsFieldFilled}
          onApplyAll={mockOnApplyAll}
          onApplyField={mockOnApplyField}
          onDismiss={mockOnDismiss}
        />
      );

      expect(getByTestId('use-title')).toBeTruthy();
      expect(getByTestId('use-category')).toBeTruthy();
      expect(getByTestId('use-condition')).toBeTruthy();
      expect(getByTestId('use-brand')).toBeTruthy();
      expect(getByTestId('use-color')).toBeTruthy();
      expect(getByTestId('use-age_group')).toBeTruthy();
      expect(getByTestId('use-gender')).toBeTruthy();
    });

    it('calls onApplyField with correct field and value', () => {
      const { getByTestId } = render(
        <AIAnalysisCard
          analysis={mockAnalysis}
          isFieldFilled={mockIsFieldFilled}
          onApplyAll={mockOnApplyAll}
          onApplyField={mockOnApplyField}
          onDismiss={mockOnDismiss}
        />
      );

      fireEvent.press(getByTestId('use-title'));
      expect(mockOnApplyField).toHaveBeenCalledWith('title', 'Nike Air Max Sneakers Size 5');

      fireEvent.press(getByTestId('use-brand'));
      expect(mockOnApplyField).toHaveBeenCalledWith('brand', 'Nike');
    });

    it('shows "Filled" for already filled fields', () => {
      mockIsFieldFilled.mockImplementation((field) => field === 'title');

      const { getByText, getAllByText } = render(
        <AIAnalysisCard
          analysis={mockAnalysis}
          isFieldFilled={mockIsFieldFilled}
          onApplyAll={mockOnApplyAll}
          onApplyField={mockOnApplyField}
          onDismiss={mockOnDismiss}
        />
      );

      // Should have at least one "Filled" button (for title)
      const filledButtons = getAllByText('Filled');
      expect(filledButtons.length).toBeGreaterThanOrEqual(1);
    });

    it('shows "Use" for empty fields', () => {
      const { getAllByText } = render(
        <AIAnalysisCard
          analysis={mockAnalysis}
          isFieldFilled={mockIsFieldFilled}
          onApplyAll={mockOnApplyAll}
          onApplyField={mockOnApplyField}
          onDismiss={mockOnDismiss}
        />
      );

      const useButtons = getAllByText('Use');
      expect(useButtons.length).toBeGreaterThan(0);
    });
  });

  describe('Dismiss Button', () => {
    it('renders dismiss button', () => {
      const { getByTestId } = render(
        <AIAnalysisCard
          analysis={mockAnalysis}
          isFieldFilled={mockIsFieldFilled}
          onApplyAll={mockOnApplyAll}
          onApplyField={mockOnApplyField}
          onDismiss={mockOnDismiss}
        />
      );

      expect(getByTestId('dismiss-ai-card')).toBeTruthy();
    });

    it('calls onDismiss when button is pressed', () => {
      const { getByTestId } = render(
        <AIAnalysisCard
          analysis={mockAnalysis}
          isFieldFilled={mockIsFieldFilled}
          onApplyAll={mockOnApplyAll}
          onApplyField={mockOnApplyField}
          onDismiss={mockOnDismiss}
        />
      );

      fireEvent.press(getByTestId('dismiss-ai-card'));
      expect(mockOnDismiss).toHaveBeenCalledTimes(1);
    });
  });

  describe('Accessibility', () => {
    it('has accessible labels for Use buttons', () => {
      const { getByLabelText } = render(
        <AIAnalysisCard
          analysis={mockAnalysis}
          isFieldFilled={mockIsFieldFilled}
          onApplyAll={mockOnApplyAll}
          onApplyField={mockOnApplyField}
          onDismiss={mockOnDismiss}
        />
      );

      expect(getByLabelText('Use AI suggestion for Title')).toBeTruthy();
      expect(getByLabelText('Use AI suggestion for Brand')).toBeTruthy();
    });

    it('has accessible hints for filled fields', () => {
      mockIsFieldFilled.mockImplementation((field) => field === 'title');

      const { getByA11yHint } = render(
        <AIAnalysisCard
          analysis={mockAnalysis}
          isFieldFilled={mockIsFieldFilled}
          onApplyAll={mockOnApplyAll}
          onApplyField={mockOnApplyField}
          onDismiss={mockOnDismiss}
        />
      );

      expect(getByA11yHint('Field already filled')).toBeTruthy();
    });

    it('has accessible label for Apply All button', () => {
      const { getByLabelText } = render(
        <AIAnalysisCard
          analysis={mockAnalysis}
          isFieldFilled={mockIsFieldFilled}
          onApplyAll={mockOnApplyAll}
          onApplyField={mockOnApplyField}
          onDismiss={mockOnDismiss}
        />
      );

      expect(getByLabelText('Apply all AI suggestions to empty fields')).toBeTruthy();
    });
  });

  describe('Edge Cases', () => {
    it('handles empty analysis gracefully', () => {
      const emptyAnalysis: AIAnalysisResult = {};

      const { getByTestId } = render(
        <AIAnalysisCard
          analysis={emptyAnalysis}
          isFieldFilled={mockIsFieldFilled}
          onApplyAll={mockOnApplyAll}
          onApplyField={mockOnApplyField}
          onDismiss={mockOnDismiss}
        />
      );

      expect(getByTestId('ai-analysis-card')).toBeTruthy();
    });

    it('handles array values in colors field', () => {
      const { getByText } = render(
        <AIAnalysisCard
          analysis={mockAnalysis}
          isFieldFilled={mockIsFieldFilled}
          onApplyAll={mockOnApplyAll}
          onApplyField={mockOnApplyField}
          onDismiss={mockOnDismiss}
        />
      );

      // color field value is ['Blue', 'White'], should display as "Blue, White"
      expect(getByText('Blue, White')).toBeTruthy();
    });
  });
});

/**
 * File: p2p-kids-marketplace/src/components/__tests__/listing/CategorySelectModal.test.tsx
 * MODULE-04 LISTING-V3-008: Unit tests for CategorySelectModal
 * 
 * Test Coverage:
 * - Rendering modal when visible/hidden
 * - Search functionality
 * - Recent categories display
 * - Category selection
 * - "Other" custom category input
 * - Close functionality
 */

import React from 'react';
import { render, fireEvent } from '@testing-library/react-native';
import { CategorySelectModal, Category } from '../../listing/CategorySelectModal';

const mockCategories: Category[] = [
  { id: 'cat-1', name: 'Shoes', icon: '👟' },
  { id: 'cat-2', name: 'Clothing', icon: '👕' },
  { id: 'cat-3', name: 'Toys', icon: '🧸' },
  { id: 'cat-4', name: 'Books', icon: '📚' },
  { id: 'cat-5', name: 'Electronics', icon: '📱' },
];

const mockRecent: Category[] = [
  { id: 'cat-1', name: 'Shoes', icon: '👟' },
  { id: 'cat-2', name: 'Clothing', icon: '👕' },
];

describe('CategorySelectModal', () => {
  const mockOnSelect = jest.fn();
  const mockOnSelectOther = jest.fn();
  const mockOnClose = jest.fn();

  beforeEach(() => {
    jest.clearAllMocks();
  });

  describe('Visibility', () => {
    it('renders when visible is true', () => {
      const { getByTestId } = render(
        <CategorySelectModal
          visible={true}
          categories={mockCategories}
          recent={mockRecent}
          onSelect={mockOnSelect}
          onSelectOther={mockOnSelectOther}
          onClose={mockOnClose}
        />
      );

      expect(getByTestId('category-select-modal')).toBeTruthy();
    });

    it('does not render when visible is false', () => {
      const { queryByTestId } = render(
        <CategorySelectModal
          visible={false}
          categories={mockCategories}
          recent={mockRecent}
          onSelect={mockOnSelect}
          onSelectOther={mockOnSelectOther}
          onClose={mockOnClose}
        />
      );

      expect(queryByTestId('category-select-modal')).toBeNull();
    });
  });

  describe('Search Functionality', () => {
    it('renders search input', () => {
      const { getByTestId } = render(
        <CategorySelectModal
          visible={true}
          categories={mockCategories}
          recent={mockRecent}
          onSelect={mockOnSelect}
          onSelectOther={mockOnSelectOther}
          onClose={mockOnClose}
        />
      );

      expect(getByTestId('category-search-input')).toBeTruthy();
    });

    it('filters categories based on search query', () => {
      const { getByTestId, getByText, queryByText } = render(
        <CategorySelectModal
          visible={true}
          categories={mockCategories}
          recent={mockRecent}
          onSelect={mockOnSelect}
          onSelectOther={mockOnSelectOther}
          onClose={mockOnClose}
        />
      );

      const searchInput = getByTestId('category-search-input');
      fireEvent.changeText(searchInput, 'Shoes');

      expect(getByText('Shoes')).toBeTruthy();
      expect(queryByText('Toys')).toBeNull();
    });

    it('shows all categories when search is empty', () => {
      const { getByText } = render(
        <CategorySelectModal
          visible={true}
          categories={mockCategories}
          recent={mockRecent}
          onSelect={mockOnSelect}
          onSelectOther={mockOnSelectOther}
          onClose={mockOnClose}
        />
      );

      expect(getByText('Shoes')).toBeTruthy();
      expect(getByText('Clothing')).toBeTruthy();
      expect(getByText('Toys')).toBeTruthy();
      expect(getByText('Books')).toBeTruthy();
      expect(getByText('Electronics')).toBeTruthy();
    });

    it('shows empty state when no results', () => {
      const { getByTestId, getByText } = render(
        <CategorySelectModal
          visible={true}
          categories={mockCategories}
          recent={mockRecent}
          onSelect={mockOnSelect}
          onSelectOther={mockOnSelectOther}
          onClose={mockOnClose}
        />
      );

      const searchInput = getByTestId('category-search-input');
      fireEvent.changeText(searchInput, 'NonexistentCategory');

      expect(getByText('No categories found')).toBeTruthy();
    });
  });

  describe('Recent Categories', () => {
    it('displays recent categories when not searching', () => {
      const { getByText, getByTestId } = render(
        <CategorySelectModal
          visible={true}
          categories={mockCategories}
          recent={mockRecent}
          onSelect={mockOnSelect}
          onSelectOther={mockOnSelectOther}
          onClose={mockOnClose}
        />
      );

      expect(getByText('Recent')).toBeTruthy();
      expect(getByTestId('recent-cat-1')).toBeTruthy();
      expect(getByTestId('recent-cat-2')).toBeTruthy();
    });

    it('hides recent categories when searching', () => {
      const { getByTestId, queryByText } = render(
        <CategorySelectModal
          visible={true}
          categories={mockCategories}
          recent={mockRecent}
          onSelect={mockOnSelect}
          onSelectOther={mockOnSelectOther}
          onClose={mockOnClose}
        />
      );

      const searchInput = getByTestId('category-search-input');
      fireEvent.changeText(searchInput, 'Shoes');

