    it('shows selected state visually', () => {
      const { getByTestId } = render(
        <GenderSelector
          value="boy"
          onChange={mockOnChange}
        />
      );

      const selectedPill = getByTestId('gender-boy');
      expect(selectedPill.props.accessibilityState).toEqual({ selected: true });
