  {
    tier: 'fair_price',
    label: 'Fair Price',
    price: 13.99,
    description: 'Balanced pricing',
  },
  {
    tier: 'asking_price',
    label: 'Asking Price',
    price: 17.99,
    description: 'Standard market rate',
  },
  {
    tier: 'almost_new',
    label: 'Almost New',
    price: 21.99,
    description: 'Premium pricing',
  },
