    it('displays tier descriptions', () => {
      const { getByText } = render(
        <PriceSuggestionCard
          tiers={mockTiers}
          selectedTier={null}
          manualValue=""
          onSelectTier={mockOnSelectTier}
          onChangeManual={mockOnChangeManual}
