    it('displays subtitle when suggestions are available', () => {
      const { getByText } = render(
        <PriceSuggestionCard
          tiers={mockTiers}
          selectedTier={null}
          manualValue=""
          onSelectTier={mockOnSelectTier}
          onChangeManual={mockOnChangeManual}
