    it('does not display OR divider when no tiers', () => {
      const { queryByText } = render(
        <PriceSuggestionCard
          tiers={[]}
          selectedTier={null}
          manualValue=""
          onSelectTier={mockOnSelectTier}
          onChangeManual={mockOnChangeManual}
