    it('has decimal keyboard type', () => {
      const { getByTestId } = render(
        <PriceSuggestionCard
          tiers={mockTiers}
          selectedTier={null}
          manualValue=""
          onSelectTier={mockOnSelectTier}
          onChangeManual={mockOnChangeManual}
